# Let's trace the exact transformations needed
inputs = ['yfzwk', 'ijfagw', 'uhjw', 'uj', 'eb']
outputs = ['yfzwk', 'ijfagw', 'jihjw', 'cjv', 'eb']

print("Exact transformations needed:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{out}'")
    if inp != out:
        print(f"  Changes needed: ", end="")
        # Check character by character
        min_len = min(len(inp), len(out))
        changes = []
        for j in range(min_len):
            if inp[j] != out[j]:
                changes.append(f"'{inp[j]}'->{out[j]}")
        # Handle length differences
        if len(inp) != len(out):
            if len(inp) > len(out):
                changes.append(f"remove chars at end")
            else:
                changes.append(f"add chars at end")
        print(changes)
    print()

